const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const K = Number(input[0]);
const N = Number(input[1]);
const alphabet = new Set(input[2]);
const message = input[3];

let possible = true;
for (let i = 0; i < N; i++) {
  if (!alphabet.has(message[i])) {
    possible = false;
    break;
  }
}

console.log(possible ? 'S' : 'N');
